// One item per attachment that looks like a bank statement.
const STATEMENT = /\.(sta|mt940|940|txt|xml|053|camt|bai|bai2|cod|coda|zip)$/i;
const out = [];
for (const item of $input.all()) {
  for (const [key, bin] of Object.entries(item.binary || {})) {
    if (!STATEMENT.test(bin.fileName || '')) continue;
    out.push({
      json: {
        email_subject: item.json.subject || '',
        email_date: item.json.date || '',
        file_name: bin.fileName,
      },
      binary: { data: bin },
    });
  }
}
return out;

// One row per statement; a file the API rejected becomes one ERROR row.
const rows = [];
$input.all().forEach((item, i) => {
  const src = $('Statement attachments').itemMatching(i).json;
  const r = item.json;
  const base = { checked_at: new Date().toISOString(), email_subject: src.email_subject, file_name: src.file_name };
  if (!r.statements) {
    const err = r.error ?? r;
    rows.push({ json: { ...base, verdict: 'ERROR', note: (typeof err === 'string' ? err : JSON.stringify(err)).slice(0, 300) } });
    return;
  }
  for (const s of r.statements) {
    rows.push({ json: {
      ...base,
      verdict: s.audit_verdict,
      format: s.format,
      account: s.account_id,
      currency: s.currency,
      statement_ref: s.statement_reference,
      opening_balance: s.opening_balance,
      total_credits: s.total_credits,
      total_debits: s.total_debits,
      calculated_closing: s.calculated_closing_balance,
      bank_closing: s.closing_balance,
      discrepancy: s.discrepancy_amount,
      transactions: s.transaction_count,
      note: (s.audit_notes || []).join(' | ').slice(0, 300),
    } });
  }
});
return rows;

